import '../domain/task.dart';
String exportIcs(List<Task> tasks){String esc(String s)=>s.replaceAll('\\','\\\\').replaceAll(',','\\,').replaceAll(';','\\;').replaceAll('\n','\\n');final out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Barnamevar//FA'];for(final t in tasks){final d=t.due.toUtc();String stamp(DateTime x)=>'${x.year.toString().padLeft(4,'0')}${x.month.toString().padLeft(2,'0')}${x.day.toString().padLeft(2,'0')}T${x.hour.toString().padLeft(2,'0')}${x.minute.toString().padLeft(2,'0')}00Z';out.addAll(['BEGIN:VEVENT','UID:${t.id}@barnamevar','DTSTART:${stamp(d)}','SUMMARY:${esc(t.title)}','DESCRIPTION:${esc(t.note)}','END:VEVENT']);}out.add('END:VCALENDAR');return out.join('\r\n');}
